1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.sql.Date;
5	import java.time.OffsetDateTime;
6	import java.util.List;
7	import java.util.Map;
8	import org.springframework.context.annotation.Profile;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.web.bind.annotation.PostMapping;
11	import org.springframework.web.bind.annotation.RequestBody;
12	import org.springframework.web.bind.annotation.RequestMapping;
13	import org.springframework.web.bind.annotation.RestController;
14	
15	/**
16	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
17	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
18	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
19	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
20	 *
21	 * <p>{@code seed} is one helper per table so a new entity is a new {@code seedX} method plus one
22	 * call, not surgery on a growing monolith; {@code reset} is data-driven off {@link #DOMAIN_TABLES}.
23	 */
24	@Profile("harness")
25	@RestController
26	@RequestMapping("/__test__")
27	public class TestSupportController {
28	
29	    /**
30	     * Every domain table, cleared on reset. Order is irrelevant: referential integrity is lifted
31	     * for the truncate and {@code RESTART IDENTITY} resets each table's generator. Add a table here
32	     * when its schema arrives.
33	     */
34	    private static final List<String> DOMAIN_TABLES = List.of(
35	            "notes", "project_tags", "tags", "tasks", "payments", "line_items",
36	            "invoices", "contacts", "projects", "clients", "dashboard_settings");
37	
38	    private final Audit audit;
39	    private final JdbcTemplate jdbc;
40	
41	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
42	        this.audit = audit;
43	        this.jdbc = jdbc;
44	    }
45	
46	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
47	    @PostMapping("/reset")
48	    public void reset() {
49	        audit.clear();
50	        // projects references clients (FK); H2 refuses to TRUNCATE an FK-referenced table, so lift
51	        // referential integrity for the duration of the reset.
52	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
53	        try {
54	            for (String table : DOMAIN_TABLES) {
55	                jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
56	            }
57	        } finally {
58	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
59	        }
60	    }
61	
62	    /** Insert the fixture a spec needs; each table has its own {@code seedX} helper below. */
63	    @PostMapping("/seed")
64	    public void seed(@RequestBody Map<String, Object> fixture) {
65	        seedClients(fixture);
66	        seedProjects(fixture);
67	        seedContacts(fixture);
68	        seedTasks(fixture);
69	        seedTags(fixture);
70	        seedProjectTags(fixture);
71	        seedNotes(fixture);
72	        seedInvoices(fixture);
73	        seedPayments(fixture);
74	        seedDashboardSettings(fixture);
75	    }
76	
77	    private void seedDashboardSettings(Map<String, Object> fixture) {
78	        Object asOf = fixture.get("asOf");
79	        if (asOf != null) {
80	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)",
81	                    Date.valueOf(asOf.toString()));
82	        }
83	    }
84	
85	    private void seedClients(Map<String, Object> fixture) {
86	        for (Map<String, Object> c : rows(fixture, "clients")) {
87	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
88	                    id(c, "id"), c.get("name"), c.get("email"));
89	        }
90	    }
91	
92	    private void seedProjects(Map<String, Object> fixture) {
93	        for (Map<String, Object> p : rows(fixture, "projects")) {
94	            Object status = p.get("status");
95	            Object archived = p.get("archived");
96	            Object budget = p.get("budget");
97	            jdbc.update(
98	                    "INSERT INTO projects (id, name, client_id, status, archived, budget)"
99	                            + " VALUES (?, ?, ?, ?, ?, ?)",
100	                    id(p, "id"), p.get("name"), id(p, "clientId"),
101	                    status == null ? "ACTIVE" : status.toString(),
102	                    archived != null && Boolean.parseBoolean(archived.toString()),
103	                    budget == null ? null : new BigDecimal(budget.toString()));
104	        }
105	    }
106	
107	    private void seedContacts(Map<String, Object> fixture) {
108	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
109	            Object primary = ct.get("primary");
110	            jdbc.update(
111	                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary)"
112	                            + " VALUES (?, ?, ?, ?, ?, ?)",
113	                    id(ct, "id"), id(ct, "clientId"),
114	                    ct.get("name"), ct.get("email"), ct.get("role"),
115	                    primary != null && Boolean.parseBoolean(primary.toString()));
116	        }
117	    }
118	
119	    private void seedTasks(Map<String, Object> fixture) {
120	        for (Map<String, Object> t : rows(fixture, "tasks")) {
121	            Object done = t.get("done");
122	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
123	                    id(t, "id"), id(t, "projectId"), t.get("title"),
124	                    done != null && Boolean.parseBoolean(done.toString()));
125	        }
126	    }
127	
